def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= budget and bid is not None and bid >= 100:
                rich_aggressive += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    high_supply = supply >= 22
    low_supply = supply <= 17

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 1:
        urgency += 2
    if low_supply:
        urgency += 2
    elif high_supply:
        urgency -= 1
    urgency += min(desperate_count, 2)

    if urgency >= 5:
        base = 118.0
    elif urgency >= 3:
        base = 86.0
    elif urgency >= 1:
        base = 58.0
    else:
        base = 34.0

    if highest_prev >= 160:
        if urgency >= 4:
            bid = 122.0
        elif high_supply and hp >= 5:
            bid = 22.0
        else:
            bid = 41.0
    elif highest_prev >= 115:
        if urgency >= 3:
            bid = max(base, min(highest_prev + 2.5, 108.0))
        else:
            bid = max(base - 8.0, 36.0)
    elif highest_prev >= 70:
        bid = max(base, min(highest_prev + 3.0, 92.0))
    elif highest_prev > 0:
        bid = max(base, highest_prev + 4.0)
    else:
        bid = base

    if rich_aggressive >= 2 and urgency <= 2:
        bid -= 10.0

    if high_supply and urgency <= 1:
        bid -= 8.0
    if low_supply and urgency >= 2:
        bid += 10.0

    if day >= 8 and hp >= 5 and budget < 140:
        bid -= 8.0
    if day >= 8 and hp <= 3:
        bid += 12.0

    min_safe = 12.0 if hp >= 6 else 24.0
    bid = max(bid, min_safe)
    bid = min(bid, budget)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 40.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0
    if my_status['hp'] <= 3:
        return min(my_status['budget'], avg_prev * 1.1)
    if day_context['supply'] < WATER_REQ * 2:
        return min(my_status['budget'], avg_prev * 1.05)
    return min(my_status['budget'], avg_prev * 0.95)
